mapper.select:
SELECT car_id carId, license, brand, model, key_cabinet keyCabinet
FROM pubcar_car
WHERE status_cd = '0' AND car_type1 = #{carType}

    AND car_id NOT IN

        #{item}

SELECT car_id carId, license, key_cabinet keyCabinet
FROM pubcar_car
WHERE (license = #{license} OR key_cabinet = #{keyCabinet}) AND sn_id = #{snId}
  AND community_id = #{communityId}
  AND status_cd = '0'

    AND car_id <> #{carId}

LIMIT 1;

SELECT c.car_id carId, c.license, c.color, c.brand, c.model, a.frame_num frameNum, a.engine_num engineNum, a.register_date registerDate, (CASE WHEN g.totalMileage IS NULL THEN 0 ELSE g.totalMileage END) totalMileage, (CASE WHEN g.orderMileage IS NULL THEN 0 ELSE g.orderMileage END) orderMileage, (CASE WHEN g.totalDrivingTime IS NULL THEN 0 ELSE g.totalDrivingTime END) totalDrivingTime, g.orderNum, i.insurance_company insuranceCompany, i.insurance_expiration_date insuranceExpirationDate, i.quarter_review quarterReview, i.quarter_review_content quarterReviewContent, i.year_review yearReview, i.year_review_content yearReviewContent, i.maintenance_expiration_date maintenanceExpirationDate, i.maintenance_fee maintenanceFee, i.mileage, v.violation_id violationId, v.date violationDate, v.address violationAddress, v.content violationContent, v.deduction, v.fine, r.repair_id repairId, r.date repairDate, r.content repairContent, r.price repairPrice, r.declarant FROM pubcar_car c LEFT JOIN pubcar_car_attr a ON a.attr_id = c.attr_id LEFT JOIN pubcar_car_insurance i ON i.insurance_id = c.insurance_id LEFT JOIN ( SELECT n.car_id, MAX(m.end_mileage) totalMileage, SUM(m.pass_mileage) orderMileage, SUM(m.duration) totalDrivingTime, COUNT(m.mileage_id) orderNum FROM pubcar_trip_mileage m INNER JOIN pubcar_trip_car_num n ON n.driver_id = m.driver_id AND n.trip_id = m.trip_id GROUP BY n.car_id ) g ON g.car_id = c.car_id LEFT JOIN pubcar_car_violation v ON v.car_id = c.car_id LEFT JOIN pubcar_car_repair r ON r.car_id = c.car_id WHERE c.status_cd = '0' AND c.car_id IN ( SELECT temp.id FROM( SELECT car_id id FROM pubcar_car WHERE status_cd = '0'
and license like concat('%',#{license},'%')
and community_id = #{communityId}
limit #{page}, #{row}
) AS temp )

SELECT COUNT(DISTINCT c.car_id) count FROM pubcar_car c LEFT JOIN pubcar_car_attr a ON a.attr_id = c.attr_id LEFT JOIN pubcar_car_insurance i ON i.insurance_id = c.insurance_id LEFT JOIN pubcar_trip_car_num n ON n.car_id = c.car_id LEFT JOIN pubcar_trip_mileage m ON m.driver_id = n.driver_id AND m.trip_id = n.trip_id LEFT JOIN pubcar_car_violation v ON v.car_id = c.car_id LEFT JOIN pubcar_car_repair r ON r.car_id = c.car_id WHERE c.status_cd = '0'
and c.license like concat('%',#{license},'%')
and c.community_id = #{communityId}

SELECT c.car_id carId, c.license, c.brand, c.model, c.asset_num assetNum, c.seat_num seatNum, o.org_name department, (CASE WHEN g.totalMileage IS NULL THEN 0 ELSE g.totalMileage END) totalMileage, (CASE WHEN g.orderMileage IS NULL THEN 0 ELSE g.orderMileage END) orderMileage, (CASE WHEN g.totalDrivingTime IS NULL THEN 0 ELSE g.totalDrivingTime END) totalDrivingTime, (CASE WHEN g.tripNum IS NULL THEN 0 ELSE g.tripNum END) tripNum FROM pubcar_car c LEFT JOIN ( SELECT m.trip_id, m.driver_id, n.car_id, MAX(m.end_mileage) totalMileage, SUM(m.pass_mileage) orderMileage, SUM(m.duration) totalDrivingTime, COUNT(DISTINCT m.trip_id) tripNum FROM pubcar_trip_mileage m LEFT JOIN pubcar_trip_car_num n ON m.trip_id = n.trip_id AND m.driver_id = n.driver_id WHERE m.status_cd = '0' AND n.status_cd = '0'
AND m.start_time >= #{startTime}
AND m.end_time <= #{endTime}
GROUP BY n.car_id ) g ON g.car_id = c.car_id LEFT JOIN u_org o ON o.org_id = c.department_id WHERE c.status_cd = '0'
and c.license like concat('%',#{license},'%')
and c.brand like concat('%',#{brand},'%')
and c.model like concat('%',#{model},'%')
and c.asset_num like concat('%',#{assetNum},'%')
and c.department_id = #{departmentId}
and c.community_id = #{communityId}
limit #{page}, #{row}

select car_id carId, license, brand, model, key_cabinet keyCabinet, CASE car_type WHEN 1 THEN '7座以下小客车' WHEN 2 THEN '7座（含）以上小客车' WHEN 3 THEN '货车' WHEN 4 THEN '摩托车' WHEN 5 THEN '其它机动车' ELSE '其它' END carTypeName from pubcar_car where status_cd = 0 AND community_id = #{communityId}
AND car_id IN
#{item}

SELECT pc.car_id carId, MAX(ptm.end_time) returnTime, MIN(pt.start_time) reserveTime FROM pubcar_car pc LEFT JOIN pubcar_trip_car_num ptcn ON ptcn.car_id = pc.car_id AND ptcn.status_cd = '0' LEFT JOIN pubcar_trip_mileage ptm ON ptm.trip_id = ptcn.trip_id AND ptm.driver_id = ptcn.driver_id AND ptm.status_cd = '0' LEFT JOIN pubcar_trip pt ON pt.trip_id = ptcn.trip_id AND pt.status_cd = '0' AND pt.approval_status = 3 AND (pt.trip_status = 1 OR pt.trip_status = 3) AND pt.start_time >= DATE_SUB(NOW(),INTERVAL 1 day) AND pt.end_time > NOW() WHERE pc.car_id IN
#{item}
GROUP BY pc.car_id

SELECT c.b_id carBId,c.car_id carId,c.license,c.brand,c.model,c.color,c.seat_num seatNum,c.car_type carType,c.department_id departmentId,c.remark,c.asset_num assetNum,c.attr_id attrId,c.insurance_id insuranceId,c.community_id communityId, a.b_id attrBId,a.register_date registerDate,a.engine_num engineNum,a.frame_num frameNum,a.accident_situation accidentSituation,a.group_id groupId, i.b_id insuranceBId,i.quarter_review quarterReview,i.year_review yearReview,i.insurance_expiration_date insuranceExpirationDate,i.maintenance_expiration_date maintenanceExpirationDate,i.insurance_company insuranceCompany, i.quarter_review_content quarterReviewContent, i.year_review_content yearReviewContent, i.maintenance_fee maintenanceFee, i.mileage, c.key_cabinet keyCabinet, c.card_number cardNumber, c.sn_id snId, c.car_type1 carType1 FROM business_pubcar_car c LEFT JOIN business_pubcar_car_attr a ON a.attr_id = c.attr_id LEFT JOIN business_pubcar_car_insurance i ON i.insurance_id = c.insurance_id
c.operate = #{operate}
and c.b_id = #{carBId}
ORDER BY a.seq DESC,i.seq DESC LIMIT 1

mapper.insert:
insert into pubcar_car(
color, remark, car_id, license, seat_num, car_type, car_type1, sn_id, key_cabinet, card_number,
attr_id, asset_num, insurance_id,model, department_id, community_id, brand, b_id, status_cd
)
select t.color,t.remark,t.car_id,t.license,t.seat_num,t.car_type, t.car_type1, t.sn_id,t.key_cabinet,t.card_number,t.attr_id,
       t.asset_num,t.insurance_id,t.model,t.department_id,t.community_id, t.brand, t.b_id, '0'
from business_pubcar_car t
where t.operate= 'ADD'

    and t.b_id= #{carBId}


    and t.community_id= #{communityId}


    and t.user_id= #{userId}

mapper.select:
SELECT  t.car_id carId,t.`license`,t.brand,t.model,t.color,t.seat_num seatNum,t.car_type carType,uo.org_name departmentName,t.remark,t.asset_num assetNum,t.attr_id attrId,t.insurance_id insuranceId,t.community_id communityId,
        a.register_date registerDate,a.engine_num engineNum,a.frame_num frameNum,a.accident_situation accidentSituation,a.group_id groupId,
        i.quarter_review quarterReview,i.year_review yearReview,i.insurance_expiration_date insuranceExpirationDate,i.maintenance_expiration_date maintenanceExpirationDate,i.insurance_company insuranceCompany,
        i.quarter_review_content quarterReviewContent, i.year_review_content yearReviewContent, i.maintenance_fee maintenanceFee, i.mileage,
       t.key_cabinet keyCabinet, t.card_number cardNumber, t.sn_id snId, t.car_type1 carType1
FROM pubcar_car t
LEFT JOIN pubcar_car_attr a ON a.attr_id = t.attr_id
LEFT JOIN pubcar_car_insurance i ON i.insurance_id = t.insurance_id
LEFT JOIN u_org uo ON uo.org_id = t.department_id AND uo.status_cd = '0'
where t.status_cd = '0'

    and t.`license` like concat('%',#{license},'%')


    and t.color like concat('%',#{color},'%')


    and t.remark like concat('%',#{remark},'%')


    and t.car_id = #{carId}


    and t.seat_num = #{seatNum}


    and t.car_type = #{carType}


    and t.asset_num like concat('%',#{assetNum},'%')


    and t.model like concat('%',#{model},'%')


    and t.department_id = #{departmentId}


    and t.brand like concat('%',#{brand},'%')


    and t.department_id = #{departmentId}


     and t.seat_num >= #{lessSeatNum}


     and t.seat_num <= #{moreSeatNum}


    and t.register_date = #{registerDate}


    and t.engine_num like concat('%',#{engineNum},'%')


    and t.frame_num like concat('%',#{frameNum},'%')


    and t.accident_situation = #{accidentSituation}


    and t.group_id = #{groupId}


    and t.quarter_review = #{quarterReview}


    and t.year_review = #{yearReview}


    and t.insurance_expiration_date = #{insuranceExpirationDate}


    and t.maintenance_expiration_date = #{maintenanceExpirationDate}


    and t.insurance_company = #{insuranceCompany}


    and t.b_id = #{bId}


    and t.community_id = #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

